#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Render the AArch32 encoding table model as C++.

Three files come out of a Model: a32_encodings.hpp (the Form enumeration, the
Operands record and the table types), a32_encodings.cpp (the form, row,
constraint and decision-tree tables) and a32_operand_decode.cpp (one function
per distinct translation of the Decode pseudocode). The decision tree is built
here and walked by an equivalent Python function so the generator can prove,
before anything is written, that it finds the row the official index
partition names.
"""

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

import re
from dataclasses import dataclass, field

import a32_operand_codegen as codegen
import a32_profile_policy as policy
import a32_table_model as tm


GENERATED = (
    "// Generated by tests/tooling/arm64/generate_a32_encoding_table.py from "
    "the pinned Arm\n// AArch32 XML release. Do not edit."
)
NAMESPACE = "uml::cpu::arm64::aarch32"
LEAF_ROWS = 4
NO_COND = 255
NO_PROGRAM = 65535
NO_FEATURE = 255
ISA_ENUM = {"A32": "a32", "T16": "t16", "T32": "t32"}
ROW_KIND = {"instruction": 0, "unpredictable": 1, "reserved_hint": 2}
TRAIT_BITS = {name: 1 << index for index, name in enumerate(tm.TRAIT_NAMES)}
CHECKS = ("none", "coprocessor", "apsr", "fpscr")
ENUM_ORDER = ("SRType", "InstrSet", "VBitOps", "VFPNegMul", "VCGEType", "VCGTtype", "FPRounding")


def hex32(value: int) -> str:
    return f"0x{value:08x}u"


# Decision trees -------------------------------------------------------------


@dataclass
class Node:
    bit: int  # -1 for a leaf
    first: int  # leaf: offset into the leaf row list; inner: zero child
    second: int  # leaf: row count; inner: one child


@dataclass
class Trees:
    nodes: list[Node]
    leaf_rows: list[int]
    roots: dict[str, int]
    leaf_offsets: dict[tuple[int, ...], int] = field(default_factory=dict)
    # A subtree that is already in nodes, by its fields: the trees share it.
    slots: dict[tuple[int, int, int], int] = field(default_factory=dict)

    def intern(self, node: Node) -> int:
        key = (node.bit, node.first, node.second)
        slot = self.slots.get(key)
        if slot is None:
            slot = self.slots[key] = len(self.nodes)
            self.nodes.append(node)
        return slot


def _rows_for_bit(rows, indexes, bit):
    zeros, ones = [], []
    for index in indexes:
        row = rows[index]
        if row.mask >> bit & 1:
            (ones if row.value >> bit & 1 else zeros).append(index)
        else:
            zeros.append(index)
            ones.append(index)
    return zeros, ones


def _build(rows, indexes, trees: Trees, used_bits: frozenset[int]) -> int:
    if len(indexes) > LEAF_ROWS:
        best = None
        candidate_bits = {
            bit for index in indexes for bit in range(32)
            if rows[index].mask >> bit & 1 and bit not in used_bits
        }
        for bit in sorted(candidate_bits):
            zeros, ones = _rows_for_bit(rows, indexes, bit)
            if max(len(zeros), len(ones)) >= len(indexes):
                continue
            cost = (max(len(zeros), len(ones)), len(zeros) + len(ones), -bit)
            if best is None or cost < best[0]:
                best = (cost, bit, zeros, ones)
        if best is not None:
            _cost, bit, zeros, ones = best
            next_used = used_bits | {bit}
            first = _build(rows, zeros, trees, next_used)
            second = _build(rows, ones, trees, next_used)
            return trees.intern(Node(bit, first, second))
    key = tuple(indexes)
    offset = trees.leaf_offsets.get(key)
    if offset is None:
        offset = trees.leaf_offsets[key] = len(trees.leaf_rows)
        trees.leaf_rows.extend(indexes)
    return trees.intern(Node(-1, offset, len(indexes)))


def build_trees(model: tm.Model) -> tuple[Trees, list[tm.RowModel], dict[str, tuple[int, int]]]:
    """One decision tree per instruction set over the concatenated row table."""
    all_rows: list[tm.RowModel] = []
    spans: dict[str, tuple[int, int]] = {}
    for isa in ("A32", "T16", "T32"):
        start = len(all_rows)
        all_rows.extend(model.rows[isa])
        spans[isa] = (start, len(all_rows))
    trees = Trees([], [], {})
    for isa in ("A32", "T16", "T32"):
        start, end = spans[isa]
        trees.roots[isa] = _build(all_rows, list(range(start, end)), trees, frozenset())
    return trees, all_rows, spans


def walk_tree(trees: Trees, rows: list[tm.RowModel], isa: str, word: int):
    """The first row of the leaf the word reaches that matches it, or None."""
    node = trees.nodes[trees.roots[isa]]
    while node.bit >= 0:
        node = trees.nodes[node.second if word >> node.bit & 1 else node.first]
    for position in range(node.first, node.first + node.second):
        row = rows[trees.leaf_rows[position]]
        if row.matches(word):
            return row
    return None


# Header ---------------------------------------------------------------------


def _enum_declarations() -> list[str]:
    lines = []
    for name in ENUM_ORDER:
        values = codegen.ENUM_VALUES[name]
        items = ", ".join(
            codegen.sanitize(value[len(name) + 1:]) for value in values
        )
        lines.append(f"enum class {name} : std::uint8_t {{ {items} }};")
    return lines


def render_header(model: tm.Model) -> str:
    forms = model.forms
    lines = [
        "// SPDX-License-Identifier: GPL-2.0-or-later",
        GENERATED,
        "#pragma once",
        "",
        '#include "cpu/arm64/aarch32/decode_types.hpp"',
        "",
        "#include <cstddef>",
        "#include <cstdint>",
        "",
        f"namespace {NAMESPACE} {{",
        "",
        "/* The enumerations the Decode pseudocode computes operands of. */",
        *_enum_declarations(),
        "",
        "/* One value per XML encoding, in index order after the two",
        " * pseudo-forms: Undefined (no encoding) and ReservedHint (a hint",
        " * encoding no instruction owns, which executes as a NOP). */",
        "enum class Form : std::uint16_t {",
    ]
    for form in forms:
        lines.append(f"\t{form.name},")
    lines += [
        "};",
        "",
        f"inline constexpr std::size_t kFormCount = {len(forms)};",
        f"inline constexpr std::size_t kRowCount = {sum(len(r) for r in model.rows.values())};",
        f"inline constexpr std::size_t kProgramCount = {len(model.programs)};",
        "",
        "/* The values the Decode pseudocode of an encoding computes, named for",
        " * its variables (docs/a32-instruction-coverage.md). A member a form's",
        " * pseudocode does not set is zero. carry_flags means the carry-out of",
        " * an expanded immediate is the carry flag itself; carry holds the",
        " * constant carry-out otherwise. */",
        "struct Operands final {",
    ]
    for member in model.member_list:
        lines.append(f"\t{member.cpp} {member.name}{{}};")
    lines += [
        "\tbool carry_flags{};",
        "};",
        "",
        "enum class Availability : std::uint8_t {",
        "\timplemented,",
        "\t/* UNDEFINED at EL0, or outside the profile by decision. */",
        "\tundefined_at_el0,",
        "};",
        "",
        "/* A check on the fields of a form that the table cannot make; decode.cpp",
        " * resolves it (coprocessor and system-register operations, APSR forms,",
        " * VMRS/VMSR). */",
        "enum class Check : std::uint8_t { none, coprocessor, apsr, fpscr };",
        "",
        "namespace trait {",
    ]
    for name in tm.TRAIT_NAMES:
        lines.append(f"inline constexpr std::uint16_t {name} = {TRAIT_BITS[name]};")
    lines += [
        "} // namespace trait",
        "",
        f"inline constexpr std::uint8_t kNoCond = {NO_COND};",
        f"inline constexpr std::uint16_t kNoProgram = {NO_PROGRAM};",
        f"inline constexpr std::uint8_t kNoFeature = {NO_FEATURE};",
        "",
        "/* What the table records about a form. */",
        "struct FormInfo final {",
        "\tconst char *name;",
        "\tconst char *mnemonic;",
        "\t/* A word LLVM MC decodes to this encoding (zero for the pseudo-forms). */",
        "\tstd::uint32_t witness;",
        "\t/* Bits the encoding requires to be 0 or 1 (SBZ and SBO); a word that",
        "\t * differs is UNPREDICTABLE. */",
        "\tstd::uint32_t should_mask;",
        "\tstd::uint32_t should_value;",
        "\tstd::uint16_t program;",
        "\tstd::uint16_t traits;",
        "\tIsa isa;",
        "\t/* The part of the profile the form belongs to. */",
        "\tLevel level;",
        "\tAvailability availability;",
        "\tCheck check;",
        "\t/* The Feature the form needs, or kNoFeature. */",
        "\tstd::uint8_t feature;",
        "\t/* Bit position of the form's own condition field, or kNoCond. */",
        "\tstd::uint8_t cond_low;",
        "\t/* The form executes only when its condition passes. */",
        "\tbool conditional;",
        "\t/* The form is decoded but executes as a NOP at EL0 (CPS). */",
        "\tbool nop;",
        "\t/* A32 data processing with S set and Rd 15 is an exception return,",
        "\t * UNPREDICTABLE at EL0. */",
        "\tbool alu_exception_return;",
        "};",
        "",
        "/* A field-pattern predicate on up to three joined fields: the value of",
        " * the fields, most significant first, masked by keep, equals want (or",
        " * does not, when negate). */",
        "struct Constraint final {",
        "\tstd::uint8_t low[3];",
        "\tstd::uint8_t width[3];",
        "\tbool negate;",
        "\tstd::uint16_t keep;",
        "\tstd::uint16_t want;",
        "};",
        "",
        "enum class RowKind : std::uint8_t {",
        "\tinstruction,",
        "\t/* The index marks the partition UNPREDICTABLE. */",
        "\tunpredictable,",
        "\treserved_hint,",
        "};",
        "",
        "/* One partition of the encoding space the index allocates. */",
        "struct Row final {",
        "\tstd::uint32_t mask;",
        "\tstd::uint32_t value;",
        "\tstd::uint16_t form;",
        "\tRowKind kind;",
        "\tstd::uint8_t constraint_count;",
        "\tstd::uint16_t constraint_first;",
        "};",
        "",
        "/* A node of the per-instruction-set decision trees. An inner node tests",
        " * the bit and continues at its zero or one child; a leaf holds a count",
        " * of candidate rows, tried in order, at an offset in kLeafRows. A subtree",
        " * that occurs more than once is stored once, and a child precedes its",
        " * parent. */",
        "struct Node final {",
        "\tstd::int16_t bit;",
        "\tstd::uint16_t first;",
        "\tstd::uint16_t second;",
        "};",
        "",
        f"inline constexpr std::size_t kNodeCount = {len(model_nodes(model))};",
        f"inline constexpr std::size_t kLeafRowCount = {len(model_leaf_rows(model))};",
        f"inline constexpr std::size_t kConstraintCount = {len(model_constraints(model))};",
        "",
        "extern const FormInfo kForms[kFormCount];",
        "extern const Row kRows[kRowCount];",
        "extern const Constraint kConstraints[kConstraintCount];",
        "extern const Node kNodes[kNodeCount];",
        "extern const std::uint16_t kLeafRows[kLeafRowCount];",
        "/* Roots of the A32, T16 and T32 trees in kNodes. */",
        "extern const std::uint16_t kTreeRoots[3];",
        "",
        "/* Run the operand program of a form on a word. */",
        "Outcome run_program(std::uint16_t program, std::uint32_t word,",
        "\tconst Context &ctx, Operands &out) noexcept;",
        "",
        f"}} // namespace {NAMESPACE}",
        "",
    ]
    return "\n".join(lines)


# Shared tables are built once per model and cached on it.


def tables(model: tm.Model) -> dict:
    """The trees, concatenated rows and constraint pool of a model."""
    return _cache(model)


def _cache(model: tm.Model) -> dict:
    cache = getattr(model, "_render_cache", None)
    if cache is None:
        trees, rows, spans = build_trees(model)
        constraints: list[tm.ConstraintModel] = []
        sequences: dict[tuple, int] = {}
        placements: list[tuple[int, int]] = []
        for row in rows:
            first = sequences.get(row.constraints)
            if first is None:
                first = sequences[row.constraints] = len(constraints)
                constraints.extend(row.constraints)
            placements.append((first, len(row.constraints)))
        cache = {
            "trees": trees, "rows": rows, "spans": spans,
            "constraints": constraints, "placements": placements,
        }
        model._render_cache = cache
    return cache


def model_nodes(model):
    return _cache(model)["trees"].nodes


def model_leaf_rows(model):
    return _cache(model)["trees"].leaf_rows


def model_constraints(model):
    return _cache(model)["constraints"]


# Tables ---------------------------------------------------------------------


def _wrap(values: list[str], per_line: int, indent: str = "\t") -> list[str]:
    lines = []
    for start in range(0, len(values), per_line):
        lines.append(indent + ", ".join(values[start:start + per_line]) + ",")
    return lines


def render_tables(model: tm.Model, witnesses: dict[str, int]) -> str:
    cache = _cache(model)
    rows, constraints = cache["rows"], cache["constraints"]
    trees: Trees = cache["trees"]
    lines = [
        "// SPDX-License-Identifier: GPL-2.0-or-later",
        GENERATED,
        '#include "cpu/arm64/aarch32/a32_encodings.hpp"',
        "",
        f"namespace {NAMESPACE} {{",
        "",
    ]
    for position, name in enumerate(policy.FEATURE_ORDER):
        lines.append(
            f"static_assert(static_cast<unsigned>(Feature::{name}) == {position});"
        )
    for level, name in enumerate(("base", "simd", "complete")):
        lines.append(
            f"static_assert(static_cast<unsigned>(Level::{name}) == {level});"
        )
    lines += ["", "const FormInfo kForms[kFormCount] = {"]
    for form in model.forms:
        encoding = form.encoding
        mnemonic = encoding.mnemonic if encoding is not None else ""
        feature = (
            str(policy.FEATURE_ORDER.index(form.feature))
            if form.feature is not None else "kNoFeature"
        )
        traits = " | ".join(f"trait::{t}" for t in sorted(form.traits)) or "0"
        should_mask = encoding.should_mask if encoding is not None else 0
        should_value = encoding.should_value if encoding is not None else 0
        lines.append(
            "\t{"
            f'"{form.name}", "{mnemonic}", {hex32(witnesses.get(form.name, 0))}, '
            f"{hex32(should_mask)}, {hex32(should_value)}, "
            f"{form.program if form.program is not None else 'kNoProgram'}, "
            f"{traits}, Isa::{ISA_ENUM[form.isa]}, Level::{form.level}, "
            f"Availability::{form.availability}, Check::{form.check or 'none'}, "
            f"{feature}, {form.cond_low if form.cond_low is not None else 'kNoCond'}, "
            f"{'true' if form.conditional else 'false'}, "
            f"{'true' if form.nop else 'false'}, "
            f"{'true' if form.alu_exception_return else 'false'}"
            "},"
        )
    lines += ["};", "", "const Row kRows[kRowCount] = {"]
    for row, (first, count) in zip(rows, cache["placements"]):
        lines.append(
            f"\t{{{hex32(row.mask)}, {hex32(row.value)}, {row.form}, "
            f"RowKind::{row.kind}, {count}, {first}}},"
        )
    lines += ["};", "", "const Constraint kConstraints[kConstraintCount] = {"]
    for constraint in constraints:
        segments = list(constraint.segments) + [(0, 0)] * (3 - len(constraint.segments))
        lows = ", ".join(str(low) for low, _w in segments)
        widths = ", ".join(str(width) for _l, width in segments)
        lines.append(
            f"\t{{{{{lows}}}, {{{widths}}}, "
            f"{'true' if constraint.negate else 'false'}, "
            f"0x{constraint.keep:x}u, 0x{constraint.want:x}u}},"
        )
    lines += ["};", "", "const Node kNodes[kNodeCount] = {"]
    for node in trees.nodes:
        lines.append(f"\t{{{node.bit}, {node.first}, {node.second}}},")
    lines += ["};", "", "const std::uint16_t kLeafRows[kLeafRowCount] = {"]
    lines += _wrap([str(i) for i in trees.leaf_rows], 16)
    roots = ", ".join(str(trees.roots[isa]) for isa in ("A32", "T16", "T32"))
    lines += [
        "};",
        "",
        f"const std::uint16_t kTreeRoots[3] = {{{roots}}};",
        "",
        f"}} // namespace {NAMESPACE}",
        "",
    ]
    return "\n".join(lines)


# Operand programs -----------------------------------------------------------


def render_operands(model: tm.Model) -> str:
    lines = [
        "// SPDX-License-Identifier: GPL-2.0-or-later",
        GENERATED,
        '#include "cpu/arm64/aarch32/a32_encodings.hpp"',
        '#include "cpu/arm64/aarch32/decode_support.hpp"',
        "",
        "#include <bit>",
        "",
        f"namespace {NAMESPACE} {{",
        "",
        "namespace {",
        "",
    ]
    for program in model.programs:
        translation = program.translation
        lines.append(
            f"/* {program.first_form} */"
        )
        lines.append(
            f"Outcome program_{program.index}([[maybe_unused]] std::uint32_t word,"
        )
        lines.append(
            "\t[[maybe_unused]] const Context &ctx, [[maybe_unused]] Operands &out) noexcept"
        )
        lines.append("{")
        fields = {f.name: f for f in program.fields}
        for name in sorted(translation.fields_used):
            field = fields[name]
            mask = (1 << field.width) - 1
            lines.append(
                f"\tconst std::uint64_t f_{name} = (word >> {field.low}) & "
                f"UINT64_C(0x{mask:x});"
            )
        lines += translation.body
        lines.append("\treturn Outcome::ok;")
        lines += ["}", ""]
    lines += [
        "using ProgramFn = Outcome (*)(std::uint32_t, const Context &, Operands &) noexcept;",
        "",
        "const ProgramFn kPrograms[kProgramCount] = {",
    ]
    lines += _wrap([f"program_{p.index}" for p in model.programs], 6)
    lines += [
        "};",
        "",
        "} // namespace",
        "",
        "Outcome run_program(std::uint16_t program, std::uint32_t word,",
        "\tconst Context &ctx, Operands &out) noexcept",
        "{",
        "\tif (program >= kProgramCount)",
        "\t\treturn Outcome::ok;",
        "\treturn kPrograms[program](word, ctx, out);",
        "}",
        "",
        f"}} // namespace {NAMESPACE}",
        "",
    ]
    return "\n".join(lines)
